def dpage(title, body, js=""):
    return ('<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Plata · ' + title + '</title>'
            '<link href="https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700;800&display=swap" rel="stylesheet"><style>' + DASH_CSS + '</style></head><body>' + body + js + '</body></html>')

def line_svg(vals, w=420, h=110, color="#2f5bea", fill=True, dash_from=None, band=None):
    mx, mn = max(vals), min(vals); rng = (mx - mn) or 1
    pts = [(i * (w - 8) / (len(vals) - 1) + 4, h - 8 - (v - mn) / rng * (h - 20)) for i, v in enumerate(vals)]
    d = " ".join(("M" if i == 0 else "L") + f"{x:.1f},{y:.1f}" for i, (x, y) in enumerate(pts))
    out = f'<svg viewBox="0 0 {w} {h}" width="100%" height="{h}" role="img" aria-label="Gráfico de líneas" preserveAspectRatio="none">'
    if band and dash_from is not None:
        up = " ".join(("M" if i == 0 else "L") + f"{x:.1f},{max(2, y - band * (i - dash_from + 1)):.1f}" for i, (x, y) in enumerate(pts) if i >= dash_from)
        dn = " ".join(f"L{x:.1f},{min(h - 2, y + band * (i - dash_from + 1)):.1f}" for i, (x, y) in reversed(list(enumerate(pts))) if i >= dash_from)
        out += f'<path d="{up} {dn} Z" fill="{color}" opacity=".13"/>'
    if dash_from is None:
        if fill: out += f'<path d="{d} L{pts[-1][0]:.1f},{h} L{pts[0][0]:.1f},{h} Z" fill="{color}" opacity=".12"/>'
        out += f'<path d="{d}" fill="none" stroke="{color}" stroke-width="2.2"/>'
    else:
        a = " ".join(("M" if i == 0 else "L") + f"{x:.1f},{y:.1f}" for i, (x, y) in enumerate(pts[:dash_from + 1]))
        b = " ".join(("M" if i == 0 else "L") + f"{x:.1f},{y:.1f}" for i, (x, y) in enumerate(pts[dash_from:]))
        out += f'<path d="{a}" fill="none" stroke="{color}" stroke-width="2.4"/><path d="{b}" fill="none" stroke="{color}" stroke-width="2.4" stroke-dasharray="6 5"/>'
    return out + '</svg>'

def bars_html(vals, h=90, color="#2f5bea"):
    mx = max(vals)
    return '<div style="display:flex;align-items:flex-end;gap:5px;height:%dpx">' % h + "".join(f'<i style="flex:1;height:{v / mx * 100:.0f}%;background:{color};border-radius:3px 3px 0 0"></i>' for v in vals) + '</div>'

