SWITCH_JS = '<script>(function(){var c=document.getElementById("card3d");if(!c)return;document.querySelectorAll("#sw .tag").forEach(function(b){b.addEventListener("click",function(){c.style.background=b.dataset.c;c.style.transform="rotateY(18deg) rotateX(-4deg)"; setTimeout(function(){c.style.transform="rotateY(-18deg) rotateX(6deg)"},350)})})})()</script>'
PRUEBA = {"product-demo-features", "interactive-product-demo", "interactive-3d-configurator", "immersive-interactive-experience", "horizontal-scroll-journey", "real-time-monitoring", "drill-down-analytics", "faq-documentation-landing"}

def build_extra():
    out = {}
    for pid, (col, secs, nav, theme, cambia) in {**{k: (v[0], v[1], v[2], v[3], v[4]) for k, v in LANDING.items()}, **{k: v for k, v in PAGINAS.items()}}.items():
        body = NAVS[nav] + "".join(SEC[s]() for s in secs)
        title = pid.replace("-", " ").capitalize()
        out[(col, pid)] = dict(html=page(title, body, theme=theme, js=SWITCH_JS if "hero_config" in secs else ""), titulo=title, cambia=cambia,
                              antes="Sin el patrón: la oferta de Plata en una página donde compiten cinco botones del mismo peso, tres menús, una promo y un login.", prueba=pid in PRUEBA)
    for pid, html in DASH.items():
        c, a = PANEL_TXT[pid]
        out[("estilos", pid)] = dict(html=html, titulo=pid, cambia=c, antes=a, antes_file="prog-ejemplos/patrones/_sin-panel.html", prueba=pid in PRUEBA)
    return out
